"""Embed Python steps and YAML templates in the deployable composition."""

import argparse
import ast
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]
HEADER = (
    "# Copyright 2026, EOX (https://eox.at) and Versioneer (https://versioneer.at)\n"
    "# SPDX-License-Identifier: Apache-2.0\n\n"
    "# Generated by scripts/build-composition.py. Edit composition/ and templates/.\n\n"
)


class Dumper(yaml.SafeDumper):
    pass


def represent_string(dumper, value):
    return dumper.represent_scalar(
        "tag:yaml.org,2002:str", value, style="|" if "\n" in value else None
    )


Dumper.add_representer(str, represent_string)


def inline_helpers(script, helper_source, module_name="composition.helpers"):
    helper_tree = ast.parse(helper_source)
    definitions = {}
    for node in helper_tree.body:
        if isinstance(node, ast.FunctionDef):
            definitions[node.name] = node
        elif isinstance(node, (ast.Import, ast.ImportFrom)):
            for alias in node.names:
                definitions[alias.asname or alias.name] = node

    lines = script.splitlines(keepends=True)
    required = set()
    for node in ast.parse(script).body:
        if isinstance(node, ast.ImportFrom) and node.module == module_name:
            for alias in node.names:
                if alias.asname or alias.name not in definitions:
                    raise ValueError(f"Unsupported helper import: {alias.name}")
                required.add(definitions[alias.name])
            lines[node.lineno - 1 : node.end_lineno] = [""] * (
                node.end_lineno - node.lineno + 1
            )

    if not required:
        return script

    pending = list(required)
    while pending:
        for node in ast.walk(pending.pop()):
            dependency = (
                definitions.get(node.id) if isinstance(node, ast.Name) else None
            )
            if dependency is not None and dependency not in required:
                required.add(dependency)
                pending.append(dependency)

    helpers = "\n\n".join(
        ast.get_source_segment(helper_source, node)
        for node in helper_tree.body
        if node in required
    )
    return helpers + "\n\n" + "".join(lines)


def build():
    composition = yaml.safe_load((ROOT / "composition/pipeline.yaml").read_text())
    helper_source = (ROOT / "composition/helpers.py").read_text()
    renderer = (ROOT / "composition/render.py").read_text()
    for step in composition["spec"]["pipeline"]:
        data = step.get("input", {})
        script_file = data.pop("scriptFile", None)
        if not script_file:
            continue
        script = (ROOT / "composition" / script_file).read_text()
        tree = ast.parse(script)
        names = sorted(
            {
                node.args[1].value
                for node in ast.walk(tree)
                if isinstance(node, ast.Call)
                and isinstance(node.func, ast.Name)
                and node.func.id == "_render_template"
                and len(node.args) >= 2
                and isinstance(node.args[1], ast.Constant)
            }
        )
        script = inline_helpers(script, helper_source)
        data["script"] = inline_helpers(script, renderer, "composition.render")
        compile(data["script"], script_file, "exec")
        if names:
            data["templates"] = {
                name: yaml.safe_load((ROOT / "templates" / f"{name}.yaml").read_text())
                for name in names
            }
    return HEADER + yaml.dump(composition, Dumper=Dumper, sort_keys=False, width=110)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check", action="store_true", help="Reject a stale composition.yaml."
    )
    args = parser.parse_args()
    result = build()
    target = ROOT / "composition.yaml"
    if args.check:
        if not target.is_file() or target.read_text() != result:
            print(
                "composition.yaml is stale. Run python3 scripts/build-composition.py.",
                file=sys.stderr,
            )
            return 1
    else:
        target.write_text(result)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
